	// 重名报错且保留原记录
	if err := s.RegisterUpgrade("v2", []string{"v9"}); !errors.Is(err, ErrVersionExists) {
		t.Fatalf("duplicate: %v", err)
	}
	got, err := s.ListUpgrades()
	if err != nil {

