// 判断（随后更早的推进报 ErrTimeRegression）。
func TestFirstLateResultOnRunningCampaignStillAdvancesTime(t *testing.T) {
	s := setupUpgrade(t, "d1")
	spec := CampaignSpec{
		ID:            "cmp-late-first",
		Operator:      "alice",
		CreatedAt:     upBase,
		TargetVersion: "v2",
